CREATE OR REPLACE PACKAGE headcount_report AS
  FUNCTION headcount(p_dept_id IN NUMBER) RETURN NUMBER;
END headcount_report;
/
CREATE OR REPLACE PACKAGE BODY headcount_report AS
  FUNCTION headcount(p_dept_id IN NUMBER) RETURN NUMBER IS
    l_count NUMBER;
  BEGIN
    SELECT COUNT(*)
    INTO l_count
    FROM staff_v
    WHERE dept_id = p_dept_id;

    RETURN l_count;
  END headcount;
END headcount_report;
/

